with kept_keys as (select id, status from accounts intersect select id, status from accounts where balance <= 45000), verified as (select s.* from accounts s join kept_keys k on s.id = k.id and s.status = k.status) select status, round(avg(balance), 2) as avg_balance, max(balance) filter (where status = 'OPEN') as open_max_balance from verified group by 1 having max(balance) filter (where status = 'OPEN') >= 0 order by open_max_balance desc nulls first;
